import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`grant-research`,heroTitle:`Find every grant you qualify for - automatically`,heroSubtitle:`Perplexity Computer scans grant databases, matches your company profile, and prepares the full application.`,inputUrlCta:`Find my grants`,inputUrlPlaceholder:`Your company name or website`,inputUrlPrefill:`Go to {url} and analyze the organization — extract its mission, size, location, sector, programs, and any details relevant to grant eligibility. Then search federal grant databases (Grants.gov, SAM.gov), state-level funding programs, and major private foundations to find every grant and funding opportunity this organization could qualify for. For each opportunity: 1) Record the grant name, funding agency, award amount range, application deadline, and program description. 2) Check eligibility requirements against the organization's profile and note whether they qualify, partially qualify, or need clarification. 3) Score each grant by fit and estimated likelihood of approval based on the organization's alignment with funding priorities. 4) Build a comprehensive application tracker spreadsheet with columns for grant name, funder, award amount, deadline, eligibility status, fit score, application URL, and next steps. 5) Prioritize the list by fit score and deadline urgency. 6) Generate a summary report of the top 15 opportunities with a brief rationale for each and specific next steps to begin each application.`,heroOverlaySteps:[`Analyzing your organization's mission, sector, and eligibility profile`,`Searching federal, state, and private grant databases`,`Checking eligibility and scoring each opportunity by fit`,`Application tracker with deadlines, amounts, and next steps — ready to review`],generatingSteps:[`Visiting {url} to extract your organization's mission, size, sector, and programs`,`Designing an agent to search Grants.gov, state programs, and private foundations for matching opportunities`,`Configuring eligibility checks and fit scoring for each grant program`,`Setting up your prioritized application tracker with deadlines and next steps`],featureSectionTitle:`From website to funding roadmap`,featureCardTitles:[`Connects to your operations stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Google Drive, Airtable, Slack — Computer delivers your grant tracker and application materials straight into the tools your team already uses.`,`Prioritized grant list with fit scores. Application tracker with deadlines and award amounts. Eligibility notes per program. A summary report with next steps for every top opportunity.`],capabilitySectionTitle:`Your grants team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a complete funding roadmap.`,capabilityCards:[{title:`Grant Discovery`,description:`Computer can search federal, state, and private grant databases — surfacing every funding opportunity relevant to your organization's mission and sector.`},{title:`Eligibility Screening`,description:`Computer can cross-reference each grant's requirements against your organization's profile — and flag where you qualify, partially qualify, or need more info.`},{title:`Fit Scoring`,description:`Computer can rank every opportunity by alignment with your mission, likelihood of approval, and deadline urgency — so you focus on the grants worth pursuing.`},{title:`Connect Your Tools`,description:`Computer can push your grant tracker into Google Sheets, Airtable, Notion, and Google Drive — build workflows across your entire operations stack.`},{title:`Remember & Learn`,description:`Computer can remember your organization profile, past applications, and funding history across sessions — so every search gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can re-scan grant databases on a schedule and alert you when new opportunities open or application deadlines approach.`}]});export{t as default};
